/**
 * The outcome evaluator.
 *
 * After a routed model returns, the consumer must turn the real result into an {@link Outcome}: a
 * quality judgment plus the observed latency and cost. Quality can come from anything, an LLM-as-judge,
 * a regex, a classifier, or a human, so this module stays scorer-agnostic and only provides safe
 * constructors that validate the latency and cost are strictly positive (the Exponential likelihood
 * has no mass at zero) and a threshold helper that turns a numeric score into an acceptance.
 *
 * @packageDocumentation
 */

/** A quality evaluator turns a raw model result into either an acceptance boolean or a numeric score. */
type QualityEvaluator<TResult> = (result: TResult) => boolean | number;
/** True when the quality flag counts as an acceptable output. */
declare function isAccepted(quality: Outcome['quality']): boolean;
/** Build a validated {@link Outcome} from a quality flag and the observed latency and cost. */
declare function makeOutcome(quality: boolean, latencyMs: number, cost: number): Outcome;
/** An accepted outcome with the observed latency and cost. */
declare function acceptedOutcome(latencyMs: number, cost: number): Outcome;
/** A rejected outcome with the observed latency and cost. */
declare function rejectedOutcome(latencyMs: number, cost: number): Outcome;
/**
 * Turn a numeric quality score into a validated outcome: accepted when `score >= threshold`. The score
 * and threshold may be on any scale as long as they agree.
 */
declare function outcomeFromScore(score: number, threshold: number, latencyMs: number, cost: number): Outcome;
/**
 * An async quality evaluator, for an LLM-as-judge or any I/O-bound scorer. The router stays
 * provider-agnostic: you bring the judge call, this is only the type it satisfies.
 */
type AsyncQualityEvaluator<TResult> = (result: TResult) => Promise<boolean | number>;
/** Normalize an evaluator verdict to a boolean acceptance, accepting scores at or above `threshold`. */
declare function evaluate(verdict: boolean | number, threshold?: number): boolean;
/** Accept when the string output length is at least `min`, and at most `max` when given. */
declare function lengthEvaluator(min: number, max?: number): QualityEvaluator<string>;
/** Accept when the string output matches the pattern. */
declare function regexEvaluator(pattern: RegExp): QualityEvaluator<string>;
/** Accept when the string output parses as JSON. */
declare function jsonValidEvaluator(): QualityEvaluator<string>;
/** Combine evaluators so the output is accepted only when every evaluator accepts it. */
declare function combineAll<TResult>(...evaluators: ReadonlyArray<QualityEvaluator<TResult>>): QualityEvaluator<TResult>;
/** Combine evaluators so the output is accepted when any evaluator accepts it. */
declare function combineAny<TResult>(...evaluators: ReadonlyArray<QualityEvaluator<TResult>>): QualityEvaluator<TResult>;

export { type AsyncQualityEvaluator, Outcome, type QualityEvaluator, acceptedOutcome, combineAll, combineAny, evaluate, isAccepted, jsonValidEvaluator, lengthEvaluator, makeOutcome, outcomeFromScore, regexEvaluator, rejectedOutcome };
